    pub(super) receiver: std::sync::mpsc::Receiver<ScopeSubmission>,
    pub(super) phase: Arc<std::sync::atomic::AtomicU8>,
}

pub struct RootSameActorScopeEnrollmentCapabilityV1 {
    sender: std::sync::mpsc::SyncSender<ScopeSubmission>,
    phase: Arc<std::sync::atomic::AtomicU8>,
    root: codex_hepta_memory::CognitiveCheckpointPeerLifetime,
    gate: Arc<SameActorPhaseGate>,
}

/// Retain both the actual one-shot owner offer and the Root-only publication
/// capability until the original handoff has completed. Dropping an unsent
/// response closes the common phase instead of allowing a replacement offer.
pub struct RootSameActorScopedEnrollmentV1 {
    pub(crate) offer: crate::root_production_handoff::same_actor_phase::RootSameActorScopedOfferV1,
    pub(crate) publication: generation_publication::RootSameActorPublicationEnrollmentCapabilityV1,
    pub(crate) gate: Arc<SameActorPhaseGate>,
    pub(crate) closing: CloseSameActorPhaseOnDrop,
}

impl ScopeRuntime {
    pub(super) fn mint(
        root: codex_hepta_memory::CognitiveCheckpointPeerLifetime,
        gate: &Arc<SameActorPhaseGate>,
    ) -> (Self, RootSameActorScopeEnrollmentCapabilityV1) {
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        let phase = Arc::new(std::sync::atomic::AtomicU8::new(PREPARED));
        (
            Self { receiver, phase: Arc::clone(&phase) },
            RootSameActorScopeEnrollmentCapabilityV1 {
                sender, phase, root, gate: Arc::clone(gate),
            },
        )
    }

    pub(super) fn activate(&self) -> io::Result<()> {
        self.phase.compare_exchange(
            PREPARED, ACTIVE, std::sync::atomic::Ordering::AcqRel,
            std::sync::atomic::Ordering::Acquire,
        ).map_err(|_| io::Error::other("original phase scope was already activated"))?;
        Ok(())
    }
}

impl RootSameActorScopeEnrollmentCapabilityV1 {
    /// Authorize the actual Prepared profile supplied by trusted Root. The
    /// daemon must independently prove its retained original capability at
    /// the same-purpose join; this profile alone supplies no business evidence.
    pub fn register(
        self,
        profile: crate::HostAuthorityLearningProfileV1,
    ) -> io::Result<RootSameActorScopedEnrollmentV1> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        self.gate.require_open()?;
        crate::authority_host_service::generation_initial::original_root()?;
        if self.root.uid != 0
            || self.root.pid != std::process::id()
            || self.root.boot_id != std::fs::read_to_string("/proc/sys/kernel/random/boot_id")?.trim()
            || self.root.process_start_ticks != original_root_start()?
            || self.phase.compare_exchange(
                ACTIVE, CONSUMED, std::sync::atomic::Ordering::AcqRel,
                std::sync::atomic::Ordering::Acquire,
            ).is_err()
        {
            return Err(io::Error::other("original Root phase capability is unavailable"));
        }
        let (acknowledgement, receiver) = std::sync::mpsc::sync_channel(1);
        self.sender.try_send(ScopeSubmission { profile, acknowledgement })
            .map_err(|_| io::Error::other("original phase scope handoff unavailable"))?;
        self.gate.notify_original_waiters();
        let enrolled = loop {
            let epoch = self.gate.original_wait_epoch()?;
            match receiver.try_recv() {
                Ok(result) => break result.map_err(io::Error::other)?,
                Err(std::sync::mpsc::TryRecvError::Empty) => self.gate.wait_original_change(epoch)?,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    return Err(io::Error::other("original phase scope acknowledgement uncertain"));
                }
            }
        };
        self.gate.require_open()?;
        if !Arc::ptr_eq(&enrolled.gate, &self.gate) {
            return Err(io::Error::other("original phase scope acknowledgement changed its gate"));
        }
        closing.disarm();
        Ok(enrolled)
    }
}

fn original_root_start() -> io::Result<u64> {
    std::fs::read_to_string("/proc/self/stat")?
        .rsplit_once(") ")
        .and_then(|(_, fields)| fields.split_whitespace().nth(19))
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|value| *value != 0)
        .ok_or_else(|| io::Error::other("actual Root incarnation missing"))
}

//! Explicit one-shot retirement and join for the original same-actor A.
//! The Root-only profile is an authorization input. Peer JSON cannot select
//! another profile, file, owner, namespace or deadline.

use std::io;
use std::os::fd::OwnedFd;
use std::os::unix::net::UnixStream;
use std::sync::Arc;
use std::sync::atomic::AtomicU8;
use std::sync::atomic::Ordering;

use codex_hepta_contracts::HostAuthorityPeerChannel;
use codex_hepta_contracts::HostAuthorityPeerPolicy;
use serde::Deserialize;
use serde::Serialize;

use crate::HostAuthorityLearningProfileV1;
use crate::authority_host_service::HostAuthorityService;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;

const UNUSED: u8 = 0;
const RETIRE_ACCEPTED: u8 = 1;
const JOIN_ACCEPTED: u8 = 2;
const PURPOSE: &str = "hepta.same-actor-q24-phase.join.v1";

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct PhaseJoinRequest {
    pub(crate) schema: u8,
    pub(crate) purpose: String,
    pub(crate) sequence: u8,
    pub(crate) phase: String,
    pub(crate) profile: String,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct PhaseJoinResponse {
    pub(crate) schema: u8,
    pub(crate) purpose: String,
    pub(crate) sequence: u8,
    pub(crate) phase: String,
    pub(crate) profile: String,
}

/// This shared state belongs to one original Root phase. It is never decoded
/// from a descriptor and cannot be reset after an accepted or failed exchange.
pub(crate) struct OriginalInitialRetirement {
    state: AtomicU8,
    gate: Arc<SameActorPhaseGate>,
    phase: String,
}

pub(crate) struct OriginalPhaseJoined {
    phase: String,
    profile: String,
}

impl OriginalInitialRetirement {
    pub(crate) fn new(gate: &Arc<SameActorPhaseGate>, phase: &str) -> Self {
        Self { state: AtomicU8::new(UNUSED), gate: Arc::clone(gate), phase: phase.into() }
    }

    /// Initial EOF transfers only the held owner; it does not grant a phase.
    /// A separate completed join and the real durable Claim are still required.
    pub(crate) fn require_expected_eof(
        &self,
        gate: &Arc<SameActorPhaseGate>,
    ) -> io::Result<()> {
        gate.require_open()?;
        if !Arc::ptr_eq(gate, &self.gate)
            || !matches!(self.state.load(Ordering::Acquire), RETIRE_ACCEPTED | JOIN_ACCEPTED)
        {
            return Err(io::Error::other("original Initial retired without an accepted intent"));
        }
        Ok(())
    }
}

impl OriginalPhaseJoined {
    pub(crate) fn require_original_profile(
        &self,
        phase: &str,
        profile: &HostAuthorityLearningProfileV1,
        retirement: &OriginalInitialRetirement,
        gate: &Arc<SameActorPhaseGate>,
    ) -> io::Result<()> {
        gate.require_open()?;
        if self.phase != phase
            || retirement.phase != phase
            || !Arc::ptr_eq(gate, &retirement.gate)
            || self.profile != serde_json::to_string(profile).map_err(io::Error::other)?
            || retirement.state.load(Ordering::Acquire) != JOIN_ACCEPTED
        {
            return Err(io::Error::other("original completed phase join differs"));
        }
        Ok(())
    }
}

/// Called only by the same Root worker after it receives the trusted host's
/// one-shot typed profile. This returns no writable rights and creates no
/// namespace. Failure keeps the common close guard armed.
pub(crate) fn accept_original_phase_join(
    service: &HostAuthorityService,
    config: &crate::HostAuthorityServiceConfig,
    registration: &crate::HostAuthorityRegistration,
    owner: &OwnedFd,
    stream: UnixStream,
    policy: HostAuthorityPeerPolicy,
    phase: &str,
    profile: &HostAuthorityLearningProfileV1,
    retirement: &OriginalInitialRetirement,
    gate: &Arc<SameActorPhaseGate>,
) -> io::Result<OriginalPhaseJoined> {
    let mut closing = CloseSameActorPhaseOnDrop::new(gate);
    let _stream_stop = gate.retain_original_stream(&stream)?;
    if retirement.phase != phase || !Arc::ptr_eq(gate, &retirement.gate) {
        return Err(io::Error::other("original phase retirement belongs to another gate"));
    }
    let exact_profile = serde_json::to_string(profile).map_err(io::Error::other)?;
    let mut channel = HostAuthorityPeerChannel::from_stream_until(
        stream, policy, owner.try_clone()?, gate.deadline().instant(),
    ).map_err(io::Error::other)?;
    for sequence in [1_u8, 2_u8] {
        let received = channel.exchange(|bytes| {
            let _admission = gate.enter_original_lane().map_err(unavailable)?;
            service.with_learning_profile(config, registration, owner, profile, |initial, _proof| {
                profile.require_cell_scope(&initial)?;
                let request: PhaseJoinRequest =
                    serde_json::from_slice(bytes).map_err(io::Error::other)?;
                if request.schema != 1
                    || request.purpose != PURPOSE
                    || request.sequence != sequence
                    || request.phase != phase
                    || request.profile != exact_profile
                {
                    return Err(io::Error::other("original phase intent and host profile differ"));
                }
                let (before, after) = if sequence == 1 {
                    (UNUSED, RETIRE_ACCEPTED)
                } else {
                    (RETIRE_ACCEPTED, JOIN_ACCEPTED)
                };
                retirement.state.compare_exchange(
                    before, after, Ordering::AcqRel, Ordering::Acquire,
                ).map_err(|_| io::Error::other("original phase intent was already consumed"))?;
                let reply = PhaseJoinResponse {
                    schema: 1,
                    purpose: PURPOSE.into(),
                    sequence,
                    phase: phase.into(),
                    profile: exact_profile.clone(),
                };
                let raw = serde_json::to_vec(&reply).map_err(io::Error::other)?;
                if raw.len() > 16 * 1024 {
                    return Err(io::Error::other("original phase reply bound"));
                }
                gate.require_open()?;
                Ok(raw)
            }).map_err(unavailable)
        }).map_err(io::Error::other)?;
        if !received {
            return Err(io::Error::other("original phase peer closed before the join"));
        }
        // Successful framing is not enough across suspend or a concurrent
        // phase close. This check follows each actual ACK write.
        gate.require_open()?;
    }
    let joined = OriginalPhaseJoined { phase: phase.into(), profile: exact_profile };
    joined.require_original_profile(phase, profile, retirement, gate)?;
    closing.disarm();
    Ok(joined)
}

fn unavailable(_: io::Error) -> codex_hepta_contracts::HostIssuerTransportError {
    codex_hepta_contracts::HostIssuerTransportError::Unavailable
}

//! Durable once-only claim for the original same-actor A operation.
//! This is Root metadata, never a replacement source, outcome or live owner.

use std::sync::Arc;

use codex_hepta_contracts::AuthorityFrontierStore;
use codex_hepta_contracts::HostAuthorityFrontierStore;
use codex_hepta_contracts::RootAuthorityDirectory;
use codex_hepta_neuron::CellGenerationOwnerBindingV1;
use codex_hepta_types::Digest32;
use serde::Deserialize;
use serde::Serialize;

use std::io;

const RECORD_BOUND: u64 = 64 * 1024;

#[derive(Clone, Debug, Eq, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct PhaseIdentity {
    pub(crate) root: codex_hepta_memory::CognitiveCheckpointPeerLifetime,
    pub(crate) consumer: codex_hepta_memory::CognitiveCheckpointPeerLifetime,
    pub(crate) identity: String,
    pub(crate) writer: String,
    pub(crate) initial: crate::HostGenerationInitialDeploymentV1,
    pub(crate) model_reservation: String,
    pub(crate) root_end_boottime_ns: u64,
}

#[derive(Clone, Debug, Eq, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct PhaseClaim {
    /// Canonical encoding of the real prepared profile, not a new authority.
    pub(crate) learning_profile: String,
    pub(crate) initial_learning_head: String,
    pub(crate) scope: String,
    pub(crate) initial_publication: String,
    pub(crate) current_head: String,
    pub(crate) source_files: String,
    pub(crate) source_binding: CellGenerationOwnerBindingV1,
    pub(crate) source_checkpoint: String,
    pub(crate) source_observation: String,
}

#[derive(Clone, Debug, Eq, PartialEq, Deserialize, Serialize)]
#[serde(tag = "state", rename_all = "snake_case", deny_unknown_fields)]
enum PhaseState {
    Reserved,
    Claimed { claim: PhaseClaim },
    Scoped { claim: PhaseClaim, factory: String },
}

#[derive(Clone, Debug, Eq, PartialEq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct PhaseRecord {
    schema_version: u32,
    identity: PhaseIdentity,
    state: PhaseState,
}

/// A failed CAS discards the expected value permanently. It is not retried,
/// and opening the existing record never creates a fresh capability.
pub(crate) struct OriginalPhaseRecord {
    store: HostAuthorityFrontierStore<PhaseRecord>,
    owner: String,
    expected: Option<PhaseRecord>,
}

impl OriginalPhaseRecord {
    pub(crate) fn reserve(
        root: Arc<RootAuthorityDirectory>,
        identity: PhaseIdentity,
    ) -> io::Result<Self> {
        // The key uses the actual A owner, not a caller attempt identifier.
        // A different Root PID or a new scope cannot bypass an existing claim.
        let owner = format!(
            "same-actor-q24-phase/{}",
            Digest32::of_parts(&[
                b"hepta.same-actor-q24-phase.original-a.v1\0",
                &identity.initial.target.digest().map_err(io::Error::other)?,
            ]),
        );
        let initial = PhaseRecord {
            schema_version: 1,
            identity,
            state: PhaseState::Reserved,
        };
        let store = HostAuthorityFrontierStore::initialize_bounded(
            root, owner.clone(), initial.clone(), RECORD_BOUND,
        ).map_err(io::Error::other)?;
        if store.load(&owner).map_err(io::Error::other)? != initial {
            return Err(io::Error::other("original phase reservation readback differs"));
        }
        Ok(Self { store, owner, expected: Some(initial) })
    }

    pub(crate) fn identity(&self) -> io::Result<&PhaseIdentity> {
        self.expected.as_ref().map(|record| &record.identity)
            .ok_or_else(|| io::Error::other("original phase record is uncertain"))
    }

    pub(crate) fn binding(&self) -> io::Result<String> {
        let bytes = serde_json::to_vec(self.identity()?).map_err(io::Error::other)?;
        Ok(Digest32::of_parts(&[
            b"hepta.same-actor-q24-phase.original-session.v1\0", &bytes,
        ]).to_string())
    }

    pub(crate) fn claim_before_namespaces(&mut self, claim: PhaseClaim) -> io::Result<()> {
        let before = self.expected.take()
            .ok_or_else(|| io::Error::other("original phase claim is already uncertain"))?;
        if !matches!(before.state, PhaseState::Reserved) {
            return Err(io::Error::other("original phase was already claimed"));
        }
        if self.store.load(&self.owner).map_err(io::Error::other)? != before {
            return Err(io::Error::other("original phase reservation changed"));
        }
        let next = PhaseRecord {
            schema_version: 1,
            identity: before.identity.clone(),
            state: PhaseState::Claimed { claim },
        };
        self.store.compare_and_set(&self.owner, &before, &next)
            .map_err(io::Error::other)?;
        if self.store.load(&self.owner).map_err(io::Error::other)? != next {
            return Err(io::Error::other("original phase claim acknowledgement uncertain"));
        }
        self.expected = Some(next);
        Ok(())
    }

    pub(crate) fn claimed(&self) -> io::Result<&PhaseClaim> {
        match self.expected.as_ref().map(|record| &record.state) {
            Some(PhaseState::Claimed { claim } | PhaseState::Scoped { claim, .. }) => Ok(claim),
            _ => Err(io::Error::other("original durable phase claim is absent")),
        }
    }

    pub(crate) fn require_claimed(&self) -> io::Result<()> {
        let expected = self.expected.as_ref()
            .ok_or_else(|| io::Error::other("original phase record is uncertain"))?;
        if !matches!(expected.state, PhaseState::Claimed { .. })
            || self.store.load(&self.owner).map_err(io::Error::other)? != *expected
        {
            return Err(io::Error::other("original durable phase claim changed before namespace"));
        }
        Ok(())
    }

    pub(crate) fn mark_scoped_before_rights(&mut self, factory: String) -> io::Result<()> {
        let before = self.expected.take()
            .ok_or_else(|| io::Error::other("original phase scope is uncertain"))?;
        let PhaseState::Claimed { claim } = &before.state else {
            return Err(io::Error::other("original durable phase claim required"));
        };
        if self.store.load(&self.owner).map_err(io::Error::other)? != before {
            return Err(io::Error::other("original durable phase claim changed"));
        }
        let next = PhaseRecord {
            schema_version: 1,
            identity: before.identity.clone(),
            state: PhaseState::Scoped { claim: claim.clone(), factory },
        };
        self.store.compare_and_set(&self.owner, &before, &next)
            .map_err(io::Error::other)?;
        if self.store.load(&self.owner).map_err(io::Error::other)? != next {
            return Err(io::Error::other("original phase scope acknowledgement uncertain"));
        }
        self.expected = Some(next);
        Ok(())
    }

    pub(crate) fn require_scoped(&self) -> io::Result<()> {
        let expected = self.expected.as_ref()
            .ok_or_else(|| io::Error::other("original phase record is uncertain"))?;
        if !matches!(expected.state, PhaseState::Scoped { .. })
            || self.store.load(&self.owner).map_err(io::Error::other)? != *expected
        {
            return Err(io::Error::other("original once-only phase scope changed"));
        }
        Ok(())
    }
}
